insert into public.exercise_equipment_rules (id,exercise_id,rationale)
select id,exercise_id,rationale
from jsonb_to_recordset('[{"id":"auns-gym:preacher_db_preacher_curl_db_arm","exercise_id":"preacher_curl","rationale":"Reused reviewed FIT PLACE24 multi-equipment rule for identical normalized equipment IDs. preacher_curl は db と arm の両設備がある場合のみ店舗対応と判定する。"},{"id":"auns-gym:preacher_rack_preacher_curl_half_arm","exercise_id":"preacher_curl","rationale":"Reused reviewed FIT PLACE24 multi-equipment rule for identical normalized equipment IDs. preacher_curl は half と arm の両設備がある場合のみ店舗対応と判定する。"},{"id":"auns-gym:preacher_rack_preacher_curl_power_arm","exercise_id":"preacher_curl","rationale":"Reused reviewed FIT PLACE24 multi-equipment rule for identical normalized equipment IDs. preacher_curl は power と arm の両設備がある場合のみ店舗対応と判定する。"}]'::jsonb) as r(id text,exercise_id text,rationale text)
on conflict (id) do update set exercise_id=excluded.exercise_id,rationale=excluded.rationale;

insert into public.exercise_equipment_rule_items (rule_id,equipment_id)
select rule_id,equipment_id
